#!/usr/bin/env python3
"""Deliver the reviewed CASS refresh bundle into a hash-matched main checkout.

The embedded archive is transport, not an alternate production implementation.
All four production changes are applied together by the original guarded
applicator. It refuses source drift and dirty target files; it never commits,
fetches, removes files, resets a checkout, or creates a branch.
"""
import base64
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import zlib

PAYLOAD_SHA256 = "e3cd2059696178db72a0523fa4aacdb853024987b17397ed0b665b5181380aba"
PAYLOAD = """"""


def main() -> None:
    raw = zlib.decompress(base64.b64decode(PAYLOAD, validate=True))
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise SystemExit("CASS refresh payload checksum mismatch")
    files = json.loads(raw)
    if set(files) != {"apply.py", "changes.py", "src/cass/refresh.rs", "src/cass/refresh_tests.rs"}:
        raise SystemExit("Unexpected CASS refresh payload inventory")
    destination = Path(os.environ["RUNNER_TEMP"]) / (
        "cass-refresh-" + os.environ["GITHUB_RUN_ID"] + "-" + os.environ["GITHUB_RUN_ATTEMPT"]
    )
    destination.mkdir(parents=True, exist_ok=False)
    for name, text in files.items():
        target = destination / name
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open("x", encoding="utf-8", newline="\n") as output:
            output.write(text)
    subprocess.run([sys.executable, str(destination / "apply.py"), ".", "--apply"], check=True)


if __name__ == "__main__":
    main()
